// Dados fictícios usados apenas para validar o Motor de Performance.
// Nada deste node é gravado na Meta ou no Google Sheets.
const data = '2026-08-12';
const conta = 'CONTA_TESTE';

const base = [
  { id: 'ANUNCIO_A', investimento: 50, impressoes: 5000, alcance: 3000, cliques: 100, cliquesLink: 80, conversas: 10 },
  { id: 'ANUNCIO_B', investimento: 70, impressoes: 6000, alcance: 3500, cliques: 90, cliquesLink: 65, conversas: 5 },
  { id: 'ANUNCIO_C', investimento: 30, impressoes: 3000, alcance: 2200, cliques: 50, cliquesLink: 40, conversas: 0 }
];

return base.map(x => ({
  json: {
    'CHAVE REGISTRO': `${data}|${conta}|anuncio|${x.id}`,
    'DATA REFERENCIA': data,
    'CONTA ANUNCIO': conta,
    'NIVEL ANALISE': 'Anúncio',
    'ID CAMPANHA': 'CAMPANHA_TESTE',
    'NOME CAMPANHA': 'Campanha de Teste',
    'OBJETIVO': 'Conversões',
    'OBJETIVO ORIGINAL': 'CONVERSIONS',
    'ID CONJUNTO': 'CONJUNTO_TESTE',
    'NOME CONJUNTO': 'Conjunto de Teste',
    'ID ANUNCIO': x.id,
    'NOME ANUNCIO': x.id,
    'INVESTIMENTO': x.investimento,
    'IMPRESSOES': x.impressoes,
    'ALCANCE': x.alcance,
    'CLIQUES': x.cliques,
    'CLIQUES LINK': x.cliquesLink,
    'CONVERSAS INICIADAS': x.conversas,
    'ORIGEM DADOS': 'TESTE'
  }
}));

// Usa somente registros da nova base diária (Fase 1).
function n(v){if(v===undefined||v===null||v==='')return 0;if(typeof v==='number')return v;let s=String(v).replace(/\s/g,'').replace('R$','');if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');return Number(s)||0;}
function d(a,b){return b>0?a/b:null;}
function p(a,b){const v=d(a,b);return v===null?null:v*100;}
function r(v){return v===null||v===undefined?null:Number(v.toFixed(4));}
function c(o,...ks){for(const k of ks)if(o[k]!==undefined&&o[k]!==null&&o[k]!=='')return o[k];return '';}

const base=items.map(i=>{const o={};for(const [k,v] of Object.entries(i.json||{}))o[String(k).trim()]=v;return o;})
.filter(o=>String(o['CHAVE REGISTRO']||'').trim());

if(!base.length)return[{json:{status_motor:'SEM_DADOS_DIARIOS',mensagem:'Nenhum registro diário com CHAVE REGISTRO foi encontrado.'}}];

const dados=base.map(o=>{const inv=n(o.INVESTIMENTO),imp=n(o.IMPRESSOES),alc=n(o.ALCANCE),cl=n(o.CLIQUES),link=n(c(o,'CLIQUES LINK','CLIQUES LINK ')),conv=n(o['CONVERSAS INICIADAS']);return{o,data:String(o['DATA REFERENCIA']||o['DATA INCIO']||''),conta:String(o['CONTA ANUNCIO']||''),nivel:String(c(o,'NIVEL ANALISE','NÍVEL ANÁLISE')),obj:String(o['OBJETIVO ORIGINAL']||o.OBJETIVO||''),inv,imp,alc,cl,link,conv,ctr:p(cl,imp),ctrLink:p(link,imp),cpc:d(inv,cl),cpm:imp>0?inv/imp*1000:null,custo:d(inv,conv),taxa:p(conv,link),freq:d(imp,alc)};});

// Benchmark ponderado: mesmo dia + conta + nível + objetivo.
const gs=new Map();
for(const x of dados){const k=[x.data,x.conta,x.nivel,x.obj].join('|');if(!gs.has(k))gs.set(k,{q:0,inv:0,imp:0,alc:0,cl:0,link:0,conv:0});const g=gs.get(k);g.q++;g.inv+=x.inv;g.imp+=x.imp;g.alc+=x.alc;g.cl+=x.cl;g.link+=x.link;g.conv+=x.conv;}

function b(x){const g=gs.get([x.data,x.conta,x.nivel,x.obj].join('|'));return{q:g.q,inv:d(g.inv,g.q),ctrLink:p(g.link,g.imp),cpc:d(g.inv,g.cl),cpm:g.imp>0?g.inv/g.imp*1000:null,custo:d(g.inv,g.conv),taxa:p(g.conv,g.link),freq:d(g.imp,g.alc)};}

// Score técnico de eficiência. Não representa qualidade comercial do lead.
function score(x,m){let s=50;
if(x.conv>0&&x.custo&&m.custo){const z=m.custo/x.custo;if(z>=1.3)s+=20;else if(z>=1.1)s+=12;else if(z<=.7)s-=20;else if(z<=.9)s-=12;}else if(x.inv>0&&x.conv===0&&m.custo&&x.inv>=m.custo)s-=20;
if(x.ctrLink!==null&&m.ctrLink){const z=x.ctrLink/m.ctrLink;if(z>=1.3)s+=10;else if(z>=1.1)s+=5;else if(z<=.7)s-=10;else if(z<=.9)s-=5;}
if(x.cpc&&m.cpc){const z=m.cpc/x.cpc;if(z>=1.3)s+=10;else if(z>=1.1)s+=5;else if(z<=.7)s-=10;else if(z<=.9)s-=5;}
if(x.taxa!==null&&m.taxa){const z=x.taxa/m.taxa;if(z>=1.3)s+=10;else if(z>=1.1)s+=5;else if(z<=.7)s-=10;else if(z<=.9)s-=5;}
return Math.max(0,Math.min(100,s));}

return dados.map(x=>{const m=b(x);return{json:{...x.o,'CTR CALCULADO':r(x.ctr),'CTR LINK':r(x.ctrLink),'CPC CALCULADO':r(x.cpc),'CPM CALCULADO':r(x.cpm),'CUSTO CONVERSA CALCULADO':r(x.custo),'TAXA CLIQUE CONVERSA':r(x.taxa),'FREQUENCIA':r(x.freq),'MEDIA INVESTIMENTO OBJETO':r(m.inv),'MEDIA CTR LINK':r(m.ctrLink),'MEDIA CPC':r(m.cpc),'MEDIA CPM':r(m.cpm),'MEDIA CUSTO CONVERSA':r(m.custo),'MEDIA TAXA CLIQUE CONVERSA':r(m.taxa),'MEDIA FREQUENCIA':r(m.freq),'INDICE GASTO VS MEDIA':r(d(x.inv,m.inv)),'SCORE TECNICO':score(x,m),'QUANTIDADE OBJETOS BENCHMARK':m.q}};});

// Gera uma saída compacta para os próximos fluxos.
if(items.length===1&&items[0].json.status_motor==='SEM_DADOS_DIARIOS')return items;
function n(v){if(v===undefined||v===null||v==='')return 0;if(typeof v==='number')return v;let s=String(v).replace(/\s/g,'').replace('R$','');if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');return Number(s)||0;}
const rs=items.map(i=>i.json),inv=rs.reduce((s,x)=>s+n(x.INVESTIMENTO),0),conv=rs.reduce((s,x)=>s+n(x['CONVERSAS INICIADAS']),0),ord=[...rs].sort((a,b)=>n(b['SCORE TECNICO'])-n(a['SCORE TECNICO']));
function nome(x){return x['NOME ANUNCIO']||x.ANUNCIO||x['NOME CONJUNTO']||x.CONJUNTO||x['NOME CAMPANHA']||'Sem nome';}
function mini(x){return{nivel:x['NIVEL ANALISE']||x['NÍVEL ANÁLISE']||'',nome:nome(x),score:n(x['SCORE TECNICO']),investimento:n(x.INVESTIMENTO),conversas:n(x['CONVERSAS INICIADAS']),custo_conversa:x['CUSTO CONVERSA CALCULADO'],ctr_link:x['CTR LINK'],cpc:x['CPC CALCULADO']};}
return[{json:{status_motor:'OK',data_referencia:rs[0]['DATA REFERENCIA']||rs[0]['DATA INCIO']||'',quantidade_registros:rs.length,investimento_total:Number(inv.toFixed(2)),conversas_iniciadas:conv,custo_medio_por_conversa:conv>0?Number((inv/conv).toFixed(2)):null,score_tecnico_medio:Number((rs.reduce((s,x)=>s+n(x['SCORE TECNICO']),0)/rs.length).toFixed(2)),melhores_resultados:ord.slice(0,5).map(mini),resultados_para_atencao:ord.slice(-5).reverse().map(mini),registros_performance:rs}}];
